COMMENT ON COLUMN planning.project.tenant_id IS '租户ID｜敏感级别:P1-内部｜规则:所有业务唯一键必须包含tenant_id';
COMMENT ON COLUMN planning.project.business_no IS '业务单号｜敏感级别:P1-内部｜规则:租户内唯一；由core.sequence_rule生成';
COMMENT ON COLUMN planning.project.workflow_instance_id IS '流程实例ID｜敏感级别:P1-内部';
COMMENT ON COLUMN planning.project.status IS '业务状态｜敏感级别:P1-内部｜规则:仅由状态机合法迁移';
COMMENT ON COLUMN planning.project.version_no IS '乐观锁版本｜敏感级别:P1-内部｜规则:更新时version_no+1，冲突则拒绝';
COMMENT ON COLUMN planning.project.created_by IS '创建人｜敏感级别:P1-内部';
COMMENT ON COLUMN planning.project.created_at IS '创建时间｜敏感级别:P1-内部';
COMMENT ON COLUMN planning.project.updated_by IS '更新人｜敏感级别:P1-内部';
COMMENT ON COLUMN planning.project.updated_at IS '更新时间｜敏感级别:P1-内部';
COMMENT ON COLUMN planning.project.is_deleted IS '逻辑删除｜敏感级别:P1-内部';
COMMENT ON COLUMN planning.project.deleted_at IS '删除时间｜敏感级别:P1-内部';
COMMENT ON COLUMN planning.project.source_channel IS '来源渠道｜敏感级别:P1-内部';
COMMENT ON COLUMN planning.project.business_date IS '业务日期｜敏感级别:P1-内部';
COMMENT ON COLUMN planning.project.subject IS '主题｜敏感级别:P1-内部';
COMMENT ON COLUMN planning.project.reason IS '原因｜敏感级别:P1-内部';
COMMENT ON COLUMN planning.project.priority IS '优先级｜敏感级别:P1-内部';
COMMENT ON COLUMN planning.project.risk_level IS '风险等级｜敏感级别:P1-内部';
COMMENT ON COLUMN planning.project.owner_center_id IS '归属中心｜敏感级别:P1-内部';
COMMENT ON COLUMN planning.project.owner_department_id IS '归属部门｜敏感级别:P1-内部';
COMMENT ON COLUMN planning.project.owner_employee_id IS '责任人｜敏感级别:P1-内部';
COMMENT ON COLUMN planning.project.planned_start_at IS '计划开始｜敏感级别:P1-内部';
COMMENT ON COLUMN planning.project.planned_finish_at IS '计划完成｜敏感级别:P1-内部';
COMMENT ON COLUMN planning.project.actual_start_at IS '实际开始｜敏感级别:P1-内部';
COMMENT ON COLUMN planning.project.actual_end_at IS '实际完成｜敏感级别:P1-内部';
COMMENT ON COLUMN planning.project.result_summary IS '结果摘要｜敏感级别:P1-内部';
COMMENT ON COLUMN planning.project.closed_at IS '关闭时间｜敏感级别:P1-内部';
COMMENT ON COLUMN planning.project.actual_amount IS '实际金额｜敏感级别:P1-内部';
COMMENT ON COLUMN planning.project.budget_item_id IS '预算项目｜敏感级别:P1-内部';
COMMENT ON COLUMN planning.project.content_asset_no IS '内容/物料编号｜敏感级别:P1-内部';
COMMENT ON COLUMN planning.project.content_title IS '主题/标题｜敏感级别:P1-内部';
COMMENT ON COLUMN planning.project.content_type IS '内容类型｜敏感级别:P1-内部';
COMMENT ON COLUMN planning.project.copyright_info IS '版权授权信息｜敏感级别:P1-内部';
COMMENT ON COLUMN planning.project.cost_center_id IS '成本中心｜敏感级别:P1-内部';
COMMENT ON COLUMN planning.project.planned_publish_at IS '计划发布时间｜敏感级别:P1-内部';
COMMENT ON COLUMN planning.project.review_points IS '品牌/事实审核要点｜敏感级别:P1-内部';
COMMENT ON COLUMN planning.project.script_copy IS '脚本/文案｜敏感级别:P1-内部';

-- 策划项目明细项: 按field_code承载：media_metrics、publish_channels
CREATE TABLE IF NOT EXISTS planning.project_item (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    tenant_id uuid NOT NULL,
    created_by uuid,
    created_at timestamptz DEFAULT now() NOT NULL,
    updated_by uuid,
    updated_at timestamptz DEFAULT now() NOT NULL,
    is_deleted boolean DEFAULT false NOT NULL,
    deleted_at timestamptz,
    master_id uuid NOT NULL,
    field_code varchar(128) NOT NULL,
    item_seq integer DEFAULT 0 NOT NULL,
    item_key varchar(128),
    item_name varchar(255),
    item_value_text text,
    item_value_number numeric(24,8),
    item_value_json jsonb,
    related_object_type varchar(128),
    related_object_id uuid,
    amount numeric(18,2),
    quantity numeric(18,6),
    sort_no integer DEFAULT 0 NOT NULL
);
COMMENT ON TABLE planning.project_item IS '策划项目明细项｜按field_code承载：media_metrics、publish_channels';
COMMENT ON COLUMN planning.project_item.id IS '主键ID｜敏感级别:P1-内部';
COMMENT ON COLUMN planning.project_item.tenant_id IS '租户ID｜敏感级别:P1-内部｜规则:所有业务唯一键必须包含tenant_id';
COMMENT ON COLUMN planning.project_item.created_by IS '创建人｜敏感级别:P1-内部';
COMMENT ON COLUMN planning.project_item.created_at IS '创建时间｜敏感级别:P1-内部';
COMMENT ON COLUMN planning.project_item.updated_by IS '更新人｜敏感级别:P1-内部';
COMMENT ON COLUMN planning.project_item.updated_at IS '更新时间｜敏感级别:P1-内部';
COMMENT ON COLUMN planning.project_item.is_deleted IS '逻辑删除｜敏感级别:P1-内部';
COMMENT ON COLUMN planning.project_item.deleted_at IS '删除时间｜敏感级别:P1-内部';
COMMENT ON COLUMN planning.project_item.master_id IS '主表ID｜敏感级别:P1-内部';
COMMENT ON COLUMN planning.project_item.field_code IS '来源字段编码｜敏感级别:P1-内部';
COMMENT ON COLUMN planning.project_item.item_seq IS '明细序号｜敏感级别:P1-内部';
COMMENT ON COLUMN planning.project_item.item_key IS '明细键｜敏感级别:P1-内部';
COMMENT ON COLUMN planning.project_item.item_name IS '明细名称｜敏感级别:P1-内部';
COMMENT ON COLUMN planning.project_item.item_value_text IS '文本值｜敏感级别:P1-内部';
COMMENT ON COLUMN planning.project_item.item_value_number IS '数值｜敏感级别:P1-内部';
COMMENT ON COLUMN planning.project_item.item_value_json IS '结构化值｜敏感级别:P1-内部';
COMMENT ON COLUMN planning.project_item.related_object_type IS '关联对象类型｜敏感级别:P1-内部';
COMMENT ON COLUMN planning.project_item.related_object_id IS '关联对象ID｜敏感级别:P1-内部';
COMMENT ON COLUMN planning.project_item.amount IS '金额｜敏感级别:P1-内部';
COMMENT ON COLUMN planning.project_item.quantity IS '数量｜敏感级别:P1-内部';
COMMENT ON COLUMN planning.project_item.sort_no IS '排序｜敏感级别:P1-内部';
RESET ROLE;
